mapper.select:
SELECT flow_id, order_id, order_no, store_id, store_name,
       dish_id, dish_name, spec_name, quantity,
       unit_price, subtotal, order_status,
       pay_type, order_time, pay_time
FROM v_dish_flow

    AND store_id = #{storeId}
    AND order_time >= #{startDate}
    AND order_time <= #{endDate}

ORDER BY order_time DESC

SELECT receipt_date, store_id, store_name, order_count, total_amount, wechat_amount, alipay_amount, cash_amount, member_amount, avg_amount FROM v_receipt_report
AND store_id = #{storeId} AND receipt_date = #{date}
ORDER BY receipt_date DESC

SELECT dish_id, dish_name, store_id, store_name, price, dish_category_id, category_name, sale_count, total_quantity, total_amount FROM v_dish_sales_ranking
AND store_id = #{storeId}
ORDER BY total_amount DESC LIMIT #{topN}

SELECT refund_id, refund_no, order_id, order_no,
       store_id, store_name, member_id,
       refund_amount, refund_reason, refund_type,
       refund_status, refund_time, approve_time,
       operator_id, operator_name
FROM v_refund_record

    AND store_id = #{storeId}
    AND refund_time >= #{startDate}
    AND refund_time <= #{endDate}

ORDER BY refund_time DESC

SELECT t.*
FROM v_dish_flow t
INNER JOIN (
    SELECT flow_id
    FROM v_dish_flow

        AND store_id = #{storeId}
        AND order_time >= #{startDate}
        AND order_time <= #{endDate}

    ORDER BY order_time DESC
    LIMIT #{limit} OFFSET #{offset}
) tmp ON t.flow_id = tmp.flow_id
ORDER BY t.order_time DESC
